        'แฟชั่นข้างถนนด้วยการเลเยอร์เสื้อผ้าและรองเท้าสนีกเกอร์',
        'สไตล์เออร์เบิร์นที่ผสมผสานความสบายกับแฟชั่นสุดเท่',
      ],
      'casual-chic': [
        'ดูดีแบบไม่ต้องพยายามด้วยการจับคู่ที่ลงตัว',
        'สบายแต่ยังคงดูมีคลาสและเก๋ไก๋',
