/**
 * Apply Pinterest 2026 trend-based outfit combination
 */
function applyTrendBasedOutfit(
  categorized: CategorizedProducts,
  style: OutfitStyle,
  aesthetic?: AestheticCategory,
  colorPalette?: ColorPalette
): Product[] {
  // Convert style to occasion type
  const occasionMap: Record<OutfitStyle, 'work' | 'casual'> = {
    business: 'work',
    casual: 'casual',
    formal: 'casual',
    weekend: 'casual',
    date: 'casual',
    workout: 'casual',
    any: 'casual',
  }

  const occasion = occasionMap[style] || 'casual'

  // Apply trend-based combination rules
  const trendItems = applyTrendBasedCombination(categorized, {
    occasion,
    aesthetic,
    colorPalette,
  })

  return trendItems.length > 0 ? trendItems : []
}

/**
 * Generate a single outfit from categorized products
 * Enhanced with Pinterest 2026 trends support and user preference personalization
 */
export function generateOutfit(
  categorized: CategorizedProducts,
  style: OutfitStyle = 'any',
  gender?: 'men' | 'women',
  options?: {
    aesthetic?: AestheticCategory
    colorPalette?: ColorPalette
    useTrends?: boolean
    userProfile?: UserProfile | null
  }
): Outfit | null {
  const { aesthetic, colorPalette, useTrends = true, userProfile } = options || {}

  // Get user preference context if profile exists
  const userContext: UserPreferenceContext | null = userProfile ? getUserPreferenceContext(userProfile) : null

  // Use user's preferred aesthetics if available, otherwise use provided aesthetic
  let targetAesthetic = aesthetic
  if (userContext && userContext.ageAppropriateAesthetics.length > 0 && !aesthetic) {
    // Use first age-appropriate aesthetic from user preferences
    targetAesthetic = userContext.ageAppropriateAesthetics[0]
  }

  let items: Product[] = []

  // Try Pinterest 2026 trend-based combination first
  if (useTrends && (targetAesthetic || colorPalette || style === 'business' || style === 'casual')) {
    items = applyTrendBasedOutfit(categorized, style, targetAesthetic, colorPalette)

    // Deduplicate categories after trend-based combination
    if (items.length > 0) {
      items = deduplicateOutfitCategories(items, {
        aesthetic,
        colorPalette,
        occasion: style === 'business' ? 'work' : 'casual',
      })
    }
  }

  // Fallback to traditional outfit generation if trend-based didn't work
  if (items.length < 2) {
    // Strategy 1: Women's dress-based outfit
    if (gender === 'women' && categorized.dresses.length > 0) {
      const dress = randomPick(categorized.dresses)
      if (dress) items.push(dress)

      // Add shoes
      const shoes = randomPick(categorized.shoes)
      if (shoes) items.push(shoes)

      // Add accessory
      const accessory = randomPick(categorized.accessories)
      if (accessory) items.push(accessory)
    }
    // Strategy 2: Traditional top + bottom + shoes outfit
    else {
      const top = randomPick(categorized.tops)
      const bottom = randomPick(categorized.bottoms)
      const shoes = randomPick(categorized.shoes)

      if (top) items.push(top)
      if (bottom) items.push(bottom)
      if (shoes) items.push(shoes)

      // Add accessory for variety
      if (Math.random() > 0.5) {
        const accessory = randomPick(categorized.accessories)
        if (accessory) items.push(accessory)
      }
    }

    // Deduplicate categories after fallback strategy
    if (items.length > 0) {
      items = deduplicateOutfitCategories(items, {
        aesthetic,
        colorPalette,
        occasion: style === 'business' ? 'work' : 'casual',
      })
    }
  }

  // Need at least 2 items to make an outfit
  if (items.length < 2) {
    return null
  }

  // Final validation before creating outfit object
  const validationResult = validateOutfitComposition(items)
  if (!validationResult.isValid) {
    console.warn('[OutfitGenerator] Invalid composition detected, applying deduplication:', validationResult.issues)
    items = deduplicateOutfitCategories(items, {
      aesthetic,
      colorPalette,
      occasion: style === 'business' ? 'work' : 'casual',
    })
  }

  const totalPrice = items.reduce((sum, p) => sum + p.price, 0)

  // Detect aesthetic from items if not provided
  const detectedAesthetic = aesthetic || (() => {
    const keywords = items.flatMap(item =>
      `${item.name} ${item.visualDescription || ''}`.toLowerCase().split(/\s+/)
    )
    return detectAestheticFromKeywords(keywords) || undefined
  })()

  // Detect color palette from items if not provided
  const detectedPalette = colorPalette || getDominantPalette(items) || undefined

  // Generate title and personalize with user's name if available
  const baseTitle = generateOutfitTitle(items, style, detectedAesthetic)
  const personalizedTitle = userContext?.userName
    ? personalizeOutfitTitle(baseTitle, userContext.userName)
    : baseTitle

  const outfit: Outfit = {
    id: `outfit-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
    title: personalizedTitle,
    description: generateOutfitDescription(items, style, detectedAesthetic, detectedPalette),
    totalPrice,
    items,
    imageUrl: items[0]?.imageUrl,
    aesthetic: detectedAesthetic,
    colorPalette: detectedPalette,
  }

  // Re-validate to ensure deduplication worked
  const finalValidation = validateOutfitComposition(items)

  console.log('[OutfitGenerator] Generated outfit:', {
    title: outfit.title,
    itemCount: outfit.items.length,
    hasImage: !!outfit.imageUrl,
    aesthetic: outfit.aesthetic,
    colorPalette: outfit.colorPalette,
    colorCoordination: calculateColorCoordination(items),
    validationStatus: finalValidation.isValid ? 'PASSED' : 'FAILED',
  })

  return outfit
}

/**
 * Filter products by gender based on category field with strict validation
 *
 * For women's products:
 * - Category must include "women"
 * - Category must NOT include "men" (unless explicitly "women" is also present)
 * - Product name must NOT include masculine style keywords (oxford shoes, derby, brogue, men's cut)
 *
 * For men's products:
 * - Category must include "men"
 * - Category must NOT include "women"
 *
 * @param products - Array of products to filter
 * @param gender - Target gender ('men' or 'women')
 * @returns Filtered array of products matching the gender criteria
 */
export function filterProductsByGender(products: Product[], gender: 'men' | 'women'): Product[] {
  const masculineFootwearKeywords = ['oxford shoe', 'derby shoe', 'brogue shoe', 'wingtip', "men's dress shoe", "men's oxford", "men's derby"]

  return products.filter((product) => {
    const category = (product as any).category?.toLowerCase() || ''
    const productName = (product.product_name || '').toLowerCase()

    if (gender === 'men') {
      return category.includes('men') && !category.includes('women')
    } else {
      // For women's products: strict validation
      const hasWomenCategory = category.includes('women')
      const hasMenCategory = category.includes('men') && !category.includes('women')
      const hasMasculineFootwear = masculineFootwearKeywords.some(keyword => productName.includes(keyword))

      const isValid = hasWomenCategory && !hasMenCategory && !hasMasculineFootwear

      // Debug logging for filtered items
      if (!isValid && (hasMenCategory || hasMasculineFootwear)) {
        console.debug(`[Gender Filter] Excluded from women's products:`, {
          name: product.product_name,
          category: category,
          reason: hasMenCategory ? 'men category' : 'masculine footwear'
        })
      }

      return isValid
    }
  })
}

/**
 * Check if a product is women's appropriate footwear
 *
 * Women's footwear includes:
 * - Heels, pumps, stilettos, block heels
 * - Women's loafers (pointed-toe, tassel, gold hardware)
 * - Mules (heeled or flat, backless)
 * - Ballet flats, pointed-toe flats
 * - Slingback heels
 * - Women's sneakers, sandals
 *
 * Excludes masculine footwear:
 * - Oxford shoes, derby shoes, brogues
 * - Wingtips, men's dress shoes
 *
 * @param product - Product to check
 * @returns true if the product is women's appropriate footwear
 */
export function isWomenFootwear(product: Product): boolean {
  const productName = (product.product_name || '').toLowerCase()
  const description = (product.product_description || '').toLowerCase()
  const combined = `${productName} ${description}`

  // Women's footwear keywords
  const womensFootwear = [
    'heel', 'pump', 'stiletto', 'block heel',
    'women\'s loafer', 'women loafer', 'pointed-toe loafer',
    'mule', 'slingback',
    'ballet flat', 'pointed-toe flat', 'rounded flat',
    'women\'s sneaker', 'women sneaker',
    'sandal', 'women\'s sandal',
    'boot', 'ankle boot', 'knee boot' // women's boots
  ]

  // Masculine footwear keywords (to exclude)
  const masculineFootwear = [
    'oxford shoe', 'derby shoe', 'brogue',
    'wingtip', 'men\'s dress shoe',
    'men\'s oxford', 'men\'s derby',
    'men\'s loafer', 'men loafer' // unless specifically women's
  ]

  // Check if it's masculine footwear (should be excluded)
  const isMasculine = masculineFootwear.some(keyword => combined.includes(keyword))
  if (isMasculine) {
    console.debug(`[Footwear Filter] Excluded masculine footwear:`, product.product_name)
    return false
  }

  // Check if it's women's footwear
  const isWomens = womensFootwear.some(keyword => combined.includes(keyword))

  return isWomens
}

/**
 * Generate multiple outfits from product catalog
 * Enhanced with user preference personalization
 */
export function generateOutfits(
  products: Product[],
  options: {
    count?: number
    style?: OutfitStyle
    gender?: 'men' | 'women'
    priceRange?: { min: number; max: number }
    userProfile?: UserProfile | null
  } = {}
): Outfit[] {
  const { count = 5, style = 'any', gender, priceRange, userProfile } = options

  // Get user preference context if profile exists
  const userContext = userProfile ? getUserPreferenceContext(userProfile) : null

  // Use gender from user profile if available, otherwise use provided gender
  const targetGender = userProfile?.gender || gender

  // Filter by gender if specified
  let filteredProducts = targetGender ? filterProductsByGender(products, targetGender) : products

  // Filter by price range if specified
  if (priceRange) {
    filteredProducts = filteredProducts.filter(
      (p) => p.price >= priceRange.min && p.price <= priceRange.max
    )
  }

  // Filter out out-of-stock products
  filteredProducts = filteredProducts.filter((p) => p.availability !== 'out_of_stock')

  // Filter by style/occasion if products have tags
  if (style && style !== 'any') {
    const targetOccasion = style === 'business' ? 'work' : style;
    // Only filter if the product HAS an occasion tag. If not, assume it's versatile (mock Central products usually versatile).
    // Actually, for better accuracy, let's filter those that DO have tags.
    // SFERA items have tags. Central mocks don't.
    // If I enforce strict filtering, Central items (without tags) might disappear if they are not compatible?
    // Let's check matching.
    filteredProducts = filteredProducts.filter(p => {
      if (!p.occasion || p.occasion.length === 0) return true; // Keep products without tags (generic)
      return p.occasion.some(occ => occ === targetOccasion || occ === style);
    });
  }

  const categorized = categorizeProducts(filteredProducts)
  const outfits: Outfit[] = []
  const usedCombinations = new Set<string>() // Track used product combinations

  // Try to generate requested number of outfits
  let attempts = 0
  const maxAttempts = count * 5 // Increased attempts to find uniques

  const usedPrimarySkus = new Set<string>()

  while (outfits.length < count && attempts < maxAttempts) {
    // Pass user profile to outfit generation with preferred aesthetics
    const aestheticOption = userContext?.ageAppropriateAesthetics[0]
    const outfit = generateOutfit(categorized, style, targetGender, {
      aesthetic: aestheticOption,
      userProfile,
    })
    if (outfit && outfit.items.length > 0) {
      // Create a unique signature for this outfit based on product SKUs
      const signature = outfit.items.map(p => p.sku).sort().join('-')
      const primarySku = outfit.items[0].sku // Assume first item is primary (Top/Dress)

      // Check if we've already used this combination OR this primary item
      if (!usedCombinations.has(signature) && !usedPrimarySkus.has(primarySku)) {
        // Check if outfit fits price range
        if (!priceRange || (outfit.totalPrice >= priceRange.min && outfit.totalPrice <= priceRange.max)) {
          outfits.push(outfit)
          usedCombinations.add(signature)
          usedPrimarySkus.add(primarySku)
        }
      }
    }
    attempts++
  }

  return outfits
}

/**
 * Generate men's outfits
 */
export function generateMensOutfits(products: Product[], count: number = 5, style?: OutfitStyle): Outfit[] {
  return generateOutfits(products, { count, style, gender: 'men' })
}

/**
 * Generate women's outfits
 */
export function generateWomensOutfits(products: Product[], count: number = 5, style?: OutfitStyle): Outfit[] {
  return generateOutfits(products, { count, style, gender: 'women' })
}

/**
 * Generate outfit based on query context
 * Enhanced with user preference personalization
 */
export function generateOutfitsFromQuery(
  products: Product[],
  query: string,
  userProfile?: UserProfile | null
): Outfit[] {
  const lowerQuery = query.toLowerCase()

  // Determine gender from query (Default to Women for OOTDay or use user profile)
  let gender: 'men' | 'women' | undefined = userProfile?.gender || 'women'
  if (lowerQuery.includes('men') && !lowerQuery.includes('women')) {
    gender = 'men'
  } else if (lowerQuery.includes('women') || lowerQuery.includes('woman')) {
    gender = 'women'
  }

  // Determine style from query
  let style: OutfitStyle = 'any'
  if (lowerQuery.includes('business') || lowerQuery.includes('work') || lowerQuery.includes('office') || lowerQuery.includes('ทำงาน') || lowerQuery.includes('ประชุม')) {
    style = 'business'
  } else if (lowerQuery.includes('casual') || lowerQuery.includes('everyday') || lowerQuery.includes('relax') || lowerQuery.includes('เที่ยว') || lowerQuery.includes('สบาย') || lowerQuery.includes('ชิล')) {
    style = 'casual'
  } else if (lowerQuery.includes('party') || lowerQuery.includes('formal') || lowerQuery.includes('event') || lowerQuery.includes('งานแต่ง') || lowerQuery.includes('ราตรี')) {
    style = 'formal'
  } else if (lowerQuery.includes('weekend') || lowerQuery.includes('saturday') || lowerQuery.includes('sunday') || lowerQuery.includes('brunch')) {
    style = 'weekend'
  } else if (lowerQuery.includes('date') || lowerQuery.includes('dinner') || lowerQuery.includes('romantic') || lowerQuery.includes('เดท') || lowerQuery.includes('แฟน')) {
    style = 'date'
  } else if (lowerQuery.includes('workout') || lowerQuery.includes('gym') || lowerQuery.includes('sport') || lowerQuery.includes('active') || lowerQuery.includes('ออกกำลังกาย')) {
    style = 'workout'
  }

  return generateOutfits(products, { count: 5, style, gender, userProfile })
}

/**
 * Chat API Route
 * Handles AI-powered fashion recommendations
 */

import { NextRequest, NextResponse } from 'next/server'
import type { EnhancedProduct } from '@/lib/types/product-types'
import type { UserProfile } from '@/lib/types/user-profile-types'
import { loadProductsServerSide } from '@/lib/server-product-loader'
import {
  processAIChatRequest,
  getFallbackRecommendations,
  type ChatRequest,
} from '@/lib/services/ai-chat-service'
import { generateOutfitsFromQuery } from '@/lib/enhanced-outfit-generator'
import { getProductName, getProductPrice, getProductImageUrl } from '@/lib/utils/product-utils'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

export async function POST(request: NextRequest) {
  try {
    const body = await request.json()
    const { message, userPreferences, conversationHistory, sessionContext, conversationId } = body

    if (!message || typeof message !== 'string') {
      return NextResponse.json({ error: 'Message is required' }, { status: 400 })
    }

    console.log('[Chat API] Processing message:', message)

    // Log session context if provided (v2.0 feature)
    if (sessionContext) {
      console.log(`[Chat API] Session has ${sessionContext.recommendedProductIds?.length || 0} previously recommended products`)
    }

    // Load enhanced products (server-side)
    const products = await loadProductsServerSide()

    if (products.length === 0) {
      console.warn('[Chat API] No enhanced products available, falling back to mock data')
    }

    console.log(`[Chat API] Using ${products.length} enhanced products`)

    // Check if AI is enabled AND products are available
    const useAI = process.env.OPENROUTER_API_KEY !== undefined && products.length > 0

    let response

    if (useAI) {
      // Use AI-powered recommendations
      console.log('[Chat API] Using AI-powered recommendations')

      const chatRequest: ChatRequest = {
        message,
        userPreferences,
        conversationHistory,
        sessionContext, // v2.0: Include session context for duplicate prevention
        conversationId, // v2.0: Include conversation ID for session tracking
      }

      response = await processAIChatRequest(chatRequest, products)
    } else {
      // Use rule-based fallback
      console.log('[Chat API] Using rule-based recommendations (no AI key)')

      const chatRequest: ChatRequest = {
        message,
        userPreferences,
        sessionContext, // v2.0: Include session context even for fallback
        conversationId, // v2.0: Include conversation ID
      }

      response = getFallbackRecommendations(chatRequest, products)
    }

    // Convert userPreferences to UserProfile if available
    const userProfile: UserProfile | null = userPreferences ? {
      userName: userPreferences.userName || '',
      gender: 'women', // Currently fixed to women
      ageRange: userPreferences.ageRange || '20-29',
      stylePreferences: userPreferences.stylePreferences || [],
      userPhoto: userPreferences.userPhoto,
      fittingModelUrl: userPreferences.fittingModelUrl,
      onboardingCompleted: userPreferences.onboardingCompleted || false,
      createdAt: userPreferences.createdAt || new Date().toISOString(),
    } : null

    // Generate outfits from recommended products with user profile
    const outfits = generateOutfitsFromQuery(
      response.recommendedProducts || products,
      message,
      5,
      userProfile
    )

    console.log(`[Chat API] Generated ${outfits.length} outfits`)
    console.log(`[Chat API] imageRequest: ${response.imageRequest}, outfitDescription: ${response.outfitDescription ? 'yes' : 'no'}`)

    // Convert outfits to response format
    const outfitResponses = outfits.map((outfit) => ({
      id: outfit.id,
      title: outfit.title,
      description: outfit.description,
      totalPrice: outfit.totalPrice,
      items: outfit.products.map((product) => ({
        sku: product.sku,
        id: product.id,
        name: getProductName(product, 'th'),
        nameEn: getProductName(product, 'en'),
        brand: product.brand,
        price: getProductPrice(product),
        imageUrl: getProductImageUrl(product),
        onlineUrl: product.centralIntegration?.productUrl || '',
        category: product.classification?.category?.category || '',
        gender: product.classification?.gender || 'unisex',
        occasion: product.classification?.tags?.occasion || [],
        formality: product.style?.formalityLevel || 5,
        colors: [
          product.style?.colors?.primary || 'unknown',
          ...(product.style?.colors?.secondary || []),
        ].filter(Boolean),
        sizes: product.sizing?.availableSizes || [],
        availability: product.availability?.status || 'unknown',
      })),
      occasion: outfit.occasion,
      formality: outfit.formality,
      imageUrl: outfit.primaryImage,
    }))

    return NextResponse.json({
      message: response.message,
      outfits: outfitResponses,
      occasion: response.occasion,
      reasoning: response.reasoning,
      sessionContext: response.sessionContext, // v2.0: Return updated session context to client
      imageRequest: response.imageRequest, // Image generation flag
      outfitDescription: response.outfitDescription, // Outfit description for image generation
    })
  } catch (error) {
    console.error('[Chat API] Error:', error)
    return NextResponse.json(
      {
        error: 'Failed to process chat request',
        details: error instanceof Error ? error.message : 'Unknown error',
      },
      { status: 500 }
    )
  }
}

'use client'

import { useState, useCallback, useEffect } from 'react'
import Image from 'next/image'
import { Button } from '@/components/ui/button'
import { Card } from '@/components/ui/card'
import { Skeleton } from '@/components/ui/skeleton'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/components/ui/dialog'
import type { Outfit } from '@/lib/types'
import { useUserProfile } from '@/lib/hooks/useUserProfile'
import { generateTryOnLooks } from '@/lib/services/fitting-model-service'
import { Eye, Heart, Share2, Shirt, Loader2, RefreshCw, AlertCircle } from 'lucide-react'

interface OutfitRecommendationCardProps {
  outfit: Outfit
  onViewOutfit: (outfit: Outfit) => void
}

export function OutfitRecommendationCard({
  outfit,
  onViewOutfit
}: OutfitRecommendationCardProps) {
  const [isLiked, setIsLiked] = useState(false)
  const [imageError, setImageError] = useState(false)

  // Try-on state
  const [showTryOnModal, setShowTryOnModal] = useState(false)
  const [isGeneratingTryOn, setIsGeneratingTryOn] = useState(false)
  const [tryOnImageUrl, setTryOnImageUrl] = useState<string | undefined>(outfit.tryOnImageUrl)
  const [tryOnImageBase64, setTryOnImageBase64] = useState<string | undefined>(outfit.tryOnImageBase64)
  const [tryOnError, setTryOnError] = useState<string | undefined>()

  // Get user profile for fitting model
  const { profile } = useUserProfile()

  // Check if user has a fitting model
  const hasFittingModel = !!profile?.fittingModelUrl

  // Determine image source: prefer flat-lay, fallback to product thumbnail
  const flatLayImage = outfit.flatLayImageUrl || outfit.flatLayImageBase64
  const fallbackImage = outfit.imageUrl
  const displayImage = flatLayImage || fallbackImage
  const isGenerating = outfit.isGeneratingFlatLay

  // Try-on image to display
  const tryOnImage = tryOnImageUrl || tryOnImageBase64

  // Sync with outfit prop when it changes
  useEffect(() => {
    if (outfit.tryOnImageUrl) {
      setTryOnImageUrl(outfit.tryOnImageUrl)
    }
    if (outfit.tryOnImageBase64) {
      setTryOnImageBase64(outfit.tryOnImageBase64)
    }
  }, [outfit.tryOnImageUrl, outfit.tryOnImageBase64])

  /**
   * Handle try-on button click
   */
  const handleTryOn = useCallback(async () => {
    // If we already have a try-on image, just open the modal
    if (tryOnImage) {
      setShowTryOnModal(true)
      return
    }

    // Check if user has a fitting model
    if (!hasFittingModel || !profile?.fittingModelUrl) {
      setTryOnError('กรุณาอัปโหลดรูปภาพในขั้นตอนการตั้งค่าเพื่อใช้ฟีเจอร์ลองใส่')
      setShowTryOnModal(true)
      return
    }

    // Start generation
    setIsGeneratingTryOn(true)
    setTryOnError(undefined)
    setShowTryOnModal(true)

    try {
      // Extract outfit items for the prompt
      const outfitItems = outfit.items.map(item => ({
        name: item.name,
        category: item.category || item.subCategory || 'clothing',
        color: item.colors?.[0],
      }))

      // Pass flat-lay image for dual reference mode (outfit consistency)
      const result = await generateTryOnLooks({
        fittingModelImageUrl: profile.fittingModelUrl,
        outfitItems,
        outfitTitle: outfit.title,
        flatLayImageUrl: outfit.flatLayImageUrl,
        flatLayImageBase64: outfit.flatLayImageBase64,
      })

      if (result.success) {
        setTryOnImageUrl(result.imageUrl)
        setTryOnImageBase64(result.imageBase64)
        setTryOnError(undefined)
      } else {
        setTryOnError(result.message || 'ไม่สามารถสร้างรูปภาพได้ กรุณาลองอีกครั้ง')
      }
    } catch (error) {
      console.error('[TryOn] Error:', error)
      setTryOnError('เกิดข้อผิดพลาด กรุณาลองอีกครั้ง')
    } finally {
      setIsGeneratingTryOn(false)
    }
  }, [tryOnImage, hasFittingModel, profile?.fittingModelUrl, outfit])

  /**
   * Handle regenerate try-on image
   */
  const handleRegenerate = useCallback(async () => {
    // Clear current image and regenerate
    setTryOnImageUrl(undefined)
    setTryOnImageBase64(undefined)
    setIsGeneratingTryOn(true)
    setTryOnError(undefined)

    if (!profile?.fittingModelUrl) {
      setTryOnError('กรุณาอัปโหลดรูปภาพในขั้นตอนการตั้งค่าเพื่อใช้ฟีเจอร์ลองใส่')
      setIsGeneratingTryOn(false)
      return
    }

    try {
      const outfitItems = outfit.items.map(item => ({
        name: item.name,
        category: item.category || item.subCategory || 'clothing',
        color: item.colors?.[0],
      }))

      // Pass flat-lay image for dual reference mode (outfit consistency)
      const result = await generateTryOnLooks({
        fittingModelImageUrl: profile.fittingModelUrl,
        outfitItems,
        outfitTitle: outfit.title,
        flatLayImageUrl: outfit.flatLayImageUrl,
        flatLayImageBase64: outfit.flatLayImageBase64,
      })

      if (result.success) {
        setTryOnImageUrl(result.imageUrl)
        setTryOnImageBase64(result.imageBase64)
        setTryOnError(undefined)
      } else {
        setTryOnError(result.message || 'ไม่สามารถสร้างรูปภาพได้ กรุณาลองอีกครั้ง')
      }
    } catch (error) {
      console.error('[TryOn] Regenerate error:', error)
      setTryOnError('เกิดข้อผิดพลาด กรุณาลองอีกครั้ง')
    } finally {
      setIsGeneratingTryOn(false)
    }
  }, [profile?.fittingModelUrl, outfit])

  return (
    <>
      <Card className="p-3 bg-white/10 backdrop-blur-sm hover:bg-white/20 transition-colors overflow-hidden">
        {/* Flat-lay image area (square aspect ratio) */}
        <div className="relative w-full aspect-square bg-gray-100 rounded-lg overflow-hidden mb-3">
          {isGenerating ? (
            // Loading skeleton while flat-lay is generating
            <div className="absolute inset-0 flex flex-col items-center justify-center">
              <Skeleton className="w-full h-full absolute inset-0" />
              <div className="z-10 text-center px-4">
                <div className="flex justify-center mb-2">
                  <div className="flex space-x-1">
                    <div className="w-2 h-2 bg-primary rounded-full animate-bounce" />
                    <div className="w-2 h-2 bg-primary rounded-full animate-bounce" style={{ animationDelay: '0.1s' }} />
                    <div className="w-2 h-2 bg-primary rounded-full animate-bounce" style={{ animationDelay: '0.2s' }} />
                  </div>
                </div>
                <p className="text-xs text-gray-500">กำลังสร้างภาพ LOOKs...</p>
              </div>
            </div>
          ) : displayImage && !imageError ? (
            // Show flat-lay or fallback image
            <Image
              src={displayImage}
              alt={outfit.title}
              fill
              className={flatLayImage ? 'object-contain' : 'object-cover'}
              sizes="(max-width: 768px) 100vw, 400px"
              onError={() => setImageError(true)}
            />
          ) : (
            // Placeholder when no image available
            <div className="w-full h-full flex items-center justify-center bg-gray-200">
              <span className="text-gray-400 text-sm">No image</span>
            </div>
          )}
        </div>

        {/* Card content */}
        <div className="space-y-2">
          <div>
            <h4 className="font-semibold text-sm line-clamp-2">{outfit.title}</h4>
            <p className="text-xs text-muted-foreground mt-0.5">
              {outfit.items.length} ชิ้น
            </p>
          </div>

          <p className="text-base font-bold">
            ฿{outfit.totalPrice.toLocaleString()}
          </p>

          {/* Action Icons Row */}
          <div className="flex items-center gap-1.5">
            <Button
              size="sm"
              variant="ghost"
              onClick={() => onViewOutfit(outfit)}
              className="flex-1 h-8 text-xs gap-1"
            >
              <Eye className="w-3.5 h-3.5" />
              ดูลุค
            </Button>
            <Button
              size="sm"
              variant="ghost"
              onClick={handleTryOn}
              disabled={isGeneratingTryOn}
              className="h-8 px-2 text-xs gap-1"
              aria-label="ลองใส่ outfit นี้"
              title={hasFittingModel ? 'ลองใส่' : 'กรุณาอัปโหลดรูปภาพก่อน'}
            >
              {isGeneratingTryOn ? (
                <Loader2 className="w-3.5 h-3.5 animate-spin" />
              ) : (
                <Shirt className="w-3.5 h-3.5" />
              )}
              ลองใส่
            </Button>
            <Button
              size="sm"
              variant="ghost"
              onClick={() => setIsLiked(!isLiked)}
              className="h-8 w-8 p-0"
              aria-label={isLiked ? "Unlike outfit" : "Like outfit"}
            >
              <Heart className={`w-4 h-4 ${isLiked ? "fill-red-500 text-red-500" : "text-gray-600"}`} />
            </Button>
            <Button
              size="sm"
              variant="ghost"
              className="h-8 w-8 p-0"
              aria-label="Share outfit"
            >
              <Share2 className="w-4 h-4 text-gray-600" />
            </Button>
          </div>
        </div>
      </Card>

      {/* Try-On Modal */}
      <Dialog open={showTryOnModal} onOpenChange={setShowTryOnModal}>
        <DialogContent className="max-w-md mx-auto">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Shirt className="w-5 h-5" />
              ลองใส่: {outfit.title}
            </DialogTitle>
            <DialogDescription>
              ดูชุดนี้บนโมเดลของคุณ
            </DialogDescription>
          </DialogHeader>

          {/* Try-On Image Area */}
          <div className="relative w-full aspect-[3/4] bg-gray-100 rounded-lg overflow-hidden">
            {isGeneratingTryOn ? (
              // Loading state
              <div className="absolute inset-0 flex flex-col items-center justify-center">
                <Skeleton className="w-full h-full absolute inset-0" />
                <div className="z-10 text-center px-4">
                  <div className="flex justify-center mb-3">
                    <Loader2 className="w-8 h-8 text-primary animate-spin" />
                  </div>
                  <p className="text-sm text-gray-600 font-medium">กำลังสร้างรูปภาพ...</p>
                  <p className="text-xs text-gray-400 mt-1">อาจใช้เวลา 10-30 วินาที</p>
                </div>
              </div>
            ) : tryOnError ? (
              // Error state
              <div className="absolute inset-0 flex flex-col items-center justify-center p-4">
                <div className="text-center">
                  <AlertCircle className="w-12 h-12 text-red-400 mx-auto mb-3" />
                  <p className="text-sm text-gray-600 mb-4">{tryOnError}</p>
                  {hasFittingModel && (
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={handleRegenerate}
                      className="gap-2"
                    >
                      <RefreshCw className="w-4 h-4" />
                      ลองอีกครั้ง
                    </Button>
                  )}
                </div>
              </div>
            ) : tryOnImage ? (
              // Show try-on image
              <Image
                src={tryOnImage}
                alt={`ลองใส่: ${outfit.title}`}
                fill
                className="object-contain"
                sizes="(max-width: 768px) 100vw, 400px"
              />
            ) : (
              // Empty state (should not happen normally)
              <div className="w-full h-full flex items-center justify-center bg-gray-200">
                <span className="text-gray-400 text-sm">ไม่มีรูปภาพ</span>
              </div>
            )}
          </div>

          {/* Action buttons */}
          <div className="flex gap-2 mt-2">
            {tryOnImage && !isGeneratingTryOn && (
              <Button
                size="sm"
                variant="outline"
                onClick={handleRegenerate}
                className="flex-1 gap-2"
              >
                <RefreshCw className="w-4 h-4" />
                ลองใส่ใหม่
              </Button>
            )}
            <Button
              size="sm"
              variant="default"
              onClick={() => setShowTryOnModal(false)}
              className="flex-1"
            >
              ปิด
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </>
  )
}

'use client'

import { useState, useCallback, useRef, useEffect } from 'react'
import type { Product } from '@/lib/types'
import type { FlatLayItem, ImageGenerationResponse } from '@/lib/types/image-types'

/**
 * Cache configuration for localStorage
 */
const CACHE_PREFIX = 'flat-lay-'
const CACHE_TTL_MS = 7 * 24 * 60 * 60 * 1000 // 7 days in milliseconds

/**
 * Maximum concurrent generations to prevent API overload
 * Increased from 2 to 3 for faster generation
 */
const MAX_CONCURRENT_GENERATIONS = 3
let currentGenerations = 0

/**
 * Global queue for pending generation requests
 * Module-scoped to persist across component re-renders
 */
interface QueuedRequest {
  id: string
  execute: () => void
}
const generationQueue: QueuedRequest[] = []

/**
 * Process the next item in the queue if a slot is available
 */
function processQueue(): void {
  if (currentGenerations >= MAX_CONCURRENT_GENERATIONS || generationQueue.length === 0) {
    return
  }

  const nextRequest = generationQueue.shift()
  if (nextRequest) {
    nextRequest.execute()
  }
}

/**
 * Remove a request from the queue by ID
 */
function removeFromQueue(id: string): void {
  const index = generationQueue.findIndex(req => req.id === id)
  if (index !== -1) {
    generationQueue.splice(index, 1)
  }
}

/**
 * Get queue position for a given ID (0 = not in queue, 1+ = position)
 */
function getQueuePosition(id: string): number {
  const index = generationQueue.findIndex(req => req.id === id)
  return index === -1 ? 0 : index + 1
}

interface CachedImage {
  imageBase64: string
  timestamp: number
}

interface UseFlatLayGenerationOptions {
  /** Outfit ID for caching */
  outfitId: string
  /** Products to generate flat-lay image from */
  items: Product[]
  /** Occasion context for the generation */
  occasionContext?: string
}

interface UseFlatLayGenerationResult {
  /** Whether the image is currently being generated */
  isGenerating: boolean
  /** Whether the request is queued waiting for a slot */
  isQueued: boolean
  /** Position in the queue (0 = not queued, 1+ = position) */
  queuePosition: number
  /** Generated image as base64 data URL */
  flatLayImageBase64: string | undefined
  /** Error message if generation failed */
  error: string | undefined
  /** Trigger the flat-lay generation manually */
  generateFlatLay: () => void
  /** Whether the image was loaded from cache */
  isFromCache: boolean
}

/**
 * Checks if cached image is still valid (not expired)
 */
function isCacheValid(cached: CachedImage): boolean {
  const now = Date.now()
  return now - cached.timestamp < CACHE_TTL_MS
}

/**
 * Gets cached flat-lay image from localStorage
 */
function getCachedImage(outfitId: string): string | null {
  if (typeof window === 'undefined') return null

  try {
    const key = `${CACHE_PREFIX}${outfitId}`
    const cached = localStorage.getItem(key)
    if (!cached) return null

    const parsed: CachedImage = JSON.parse(cached)
    if (isCacheValid(parsed)) {
      return parsed.imageBase64
    } else {
      // Remove expired cache
      localStorage.removeItem(key)
      return null
    }
  } catch (error) {
    console.warn('[useFlatLayGeneration] Error reading cache:', error)
    return null
  }
}

/**
 * Saves generated image to localStorage cache
 * Implements automatic cache eviction when quota is exceeded
 */
function setCachedImage(outfitId: string, imageBase64: string): void {
  if (typeof window === 'undefined') return

  const key = `${CACHE_PREFIX}${outfitId}`
  const cached: CachedImage = {
    imageBase64,
    timestamp: Date.now(),
  }
  const cacheValue = JSON.stringify(cached)

  // Maximum retry attempts with progressive eviction
  const maxRetries = 3
  const evictionCounts = [1, 2, Number.MAX_SAFE_INTEGER] // Evict 1, then 2, then all remaining

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      localStorage.setItem(key, cacheValue)

      // Success - log if we had to evict entries
      if (attempt > 0) {
        console.log(`[useFlatLayGeneration] Successfully cached after evicting entries (attempt ${attempt + 1})`)
      }
      return
    } catch (error) {
      // Check if this is a QuotaExceededError
      const isQuotaError =
        error instanceof DOMException &&
        (error.name === 'QuotaExceededError' || error.name === 'NS_ERROR_DOM_QUOTA_REACHED')

      if (isQuotaError && attempt < maxRetries) {
        // Attempt cache eviction
        const entriesToEvict = evictionCounts[attempt]
        console.warn(
          `[useFlatLayGeneration] localStorage quota exceeded. ` +
          `Attempting to evict ${entriesToEvict === Number.MAX_SAFE_INTEGER ? 'all remaining' : entriesToEvict} entries...`
        )

        const evicted = evictOldestCacheEntries(entriesToEvict)
        console.log(`[useFlatLayGeneration] Evicted ${evicted} cache entries`)

        if (evicted === 0) {
          // No cache entries to evict, image might be too large
          console.warn(
            '[useFlatLayGeneration] No cache entries available to evict. ' +
            'Image may be too large for localStorage quota.'
          )
          return
        }

        // Continue to next retry attempt
        continue
      } else {
        // Non-quota error or all retries exhausted
        if (isQuotaError) {
          console.warn(
            '[useFlatLayGeneration] Failed to cache image after all eviction attempts. ' +
            'localStorage quota cannot accommodate this image.'
          )
        } else {
          console.warn('[useFlatLayGeneration] Error saving to cache:', error)
        }
        return
      }
    }
  }
}

/**
 * Cleans up expired cache entries
 * Call this periodically to prevent localStorage bloat
 */
export function cleanupExpiredCache(): void {
  if (typeof window === 'undefined') return

  try {
    const keys: string[] = []
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i)
      if (key?.startsWith(CACHE_PREFIX)) {
        keys.push(key)
      }
    }

    for (const key of keys) {
      try {
        const cached = localStorage.getItem(key)
        if (cached) {
          const parsed: CachedImage = JSON.parse(cached)
          if (!isCacheValid(parsed)) {
            localStorage.removeItem(key)
          }
        }
      } catch {
        // Invalid cache entry, remove it
        localStorage.removeItem(key)
      }
    }
  } catch (error) {
    console.warn('[useFlatLayGeneration] Error cleaning cache:', error)
  }
}

/**
 * Evicts oldest cache entries to free up localStorage space
 * @param count Number of entries to evict (default 1)
 * @returns Number of entries actually evicted
 */
function evictOldestCacheEntries(count: number = 1): number {
  if (typeof window === 'undefined') return 0

  try {
    // Collect all flat-lay cache entries with their timestamps
    const cacheEntries: Array<{ key: string; timestamp: number }> = []

    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i)
      if (key?.startsWith(CACHE_PREFIX)) {
        try {
          const cached = localStorage.getItem(key)
          if (cached) {
            const parsed: CachedImage = JSON.parse(cached)
            cacheEntries.push({ key, timestamp: parsed.timestamp })
          }
        } catch {
          // Corrupted entry, add with timestamp 0 to prioritize removal
          cacheEntries.push({ key, timestamp: 0 })
        }
      }
    }

    if (cacheEntries.length === 0) {
      return 0
    }

    // Sort by timestamp (oldest first)
    cacheEntries.sort((a, b) => a.timestamp - b.timestamp)

    // Remove the specified number of oldest entries
    const toEvict = Math.min(count, cacheEntries.length)
    let evicted = 0

    for (let i = 0; i < toEvict; i++) {
      try {
        localStorage.removeItem(cacheEntries[i].key)
        evicted++
      } catch {
        // Failed to remove, continue with others
        console.warn(`[useFlatLayGeneration] Failed to evict cache entry: ${cacheEntries[i].key}`)
      }
    }

    return evicted
  } catch (error) {
    console.warn('[useFlatLayGeneration] Error during cache eviction:', error)
    return 0
  }
}

/**
 * Transforms Product array to FlatLayItem array for API request
 */
function transformToFlatLayItems(items: Product[]): FlatLayItem[] {
  return items.map(item => ({
    name: item.name,
    category: item.subCategory || item.category || 'clothing',
    color: item.colors?.[0],
    visualDescription: item.visualDescription,
  }))
}

/**
 * Custom hook for lazy flat-lay image generation with caching
 *
 * Features:
 * - Checks localStorage cache synchronously on initial render
 * - Supports lazy loading via Intersection Observer
 * - Uses global queue system to manage concurrent generations
 * - Provides loading states, queue status, and error handling
 * - Falls back gracefully on errors
 */
export function useFlatLayGeneration({
  outfitId,
  items,
  occasionContext,
}: UseFlatLayGenerationOptions): UseFlatLayGenerationResult {
  // Initialize state synchronously from cache to prevent flicker
  const [flatLayImageBase64, setFlatLayImageBase64] = useState<string | undefined>(() => {
    const cached = getCachedImage(outfitId)
    return cached || undefined
  })
  const [isFromCache, setIsFromCache] = useState<boolean>(() => {
    return !!getCachedImage(outfitId)
  })
  const [isGenerating, setIsGenerating] = useState(false)
  const [isQueued, setIsQueued] = useState(false)
  const [queuePosition, setQueuePosition] = useState(0)
  const [error, setError] = useState<string | undefined>(undefined)

  // Track if generation has been attempted for this outfit
  const hasAttemptedRef = useRef(false)
  // Track if component is mounted
  const isMountedRef = useRef(true)
  // Track the current outfitId for cleanup
  const currentOutfitIdRef = useRef(outfitId)

  // Reset state when outfitId changes
  useEffect(() => {
    if (currentOutfitIdRef.current !== outfitId) {
      // Remove old request from queue if exists
      removeFromQueue(currentOutfitIdRef.current)

      // Check new outfit's cache
      const cached = getCachedImage(outfitId)
      if (cached) {
        setFlatLayImageBase64(cached)
        setIsFromCache(true)
        hasAttemptedRef.current = true
      } else {
        setFlatLayImageBase64(undefined)
        setIsFromCache(false)
        hasAttemptedRef.current = false
      }

      setIsGenerating(false)
      setIsQueued(false)
      setQueuePosition(0)
      setError(undefined)
      currentOutfitIdRef.current = outfitId
    }
  }, [outfitId])

  // Update queue position periodically when queued
  useEffect(() => {
    if (!isQueued) return

    const interval = setInterval(() => {
      const pos = getQueuePosition(outfitId)
      if (isMountedRef.current) {
        setQueuePosition(pos)
        if (pos === 0) {
          // No longer in queue, stop checking
          setIsQueued(false)
        }
      }
    }, 500)

    return () => clearInterval(interval)
  }, [isQueued, outfitId])

  // Cleanup on unmount
  useEffect(() => {
    isMountedRef.current = true
    return () => {
      isMountedRef.current = false
      // Remove from queue on unmount
      removeFromQueue(outfitId)
    }
  }, [outfitId])

  /**
   * Internal function to perform the actual generation
   */
  const performGeneration = useCallback(async () => {
    if (!isMountedRef.current) return

    // Mark as generating, not queued
    setIsQueued(false)
    setQueuePosition(0)
    setIsGenerating(true)
    setError(undefined)
    hasAttemptedRef.current = true
    currentGenerations++

    const flatLayItems = transformToFlatLayItems(items)

    // Retry logic with exponential backoff
    const maxRetries = 1
    let lastError: string | undefined

    for (let attempt = 0; attempt <= maxRetries; attempt++) {
      try {
        if (attempt > 0) {
          // Exponential backoff: 2^attempt * 1000ms
          const delay = Math.pow(2, attempt) * 1000
          await new Promise(resolve => setTimeout(resolve, delay))
        }

        const response = await fetch('/api/generate-image', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            generationType: 'flat-lay',
            flatLayItems,
            occasionContext,
          }),
        })

        const result: ImageGenerationResponse = await response.json()

        if (!isMountedRef.current) {
          currentGenerations--
          processQueue() // Allow next in queue to proceed
          return
        }

        if (result.success && result.imageBase64) {
          setFlatLayImageBase64(result.imageBase64)
          setIsFromCache(false)
          setError(undefined)
          // Cache the generated image
          setCachedImage(outfitId, result.imageBase64)
          currentGenerations--
          setIsGenerating(false)
          processQueue() // Process next in queue
          return
        } else {
          lastError = result.message || result.error || 'Generation failed'
        }
      } catch (err) {
        console.error('[useFlatLayGeneration] API error:', err)
        lastError = err instanceof Error ? err.message : 'Network error'
      }
    }

    // All retries failed
    if (isMountedRef.current) {
      setError(lastError)
      setIsGenerating(false)
    }
    currentGenerations--
    processQueue() // Process next in queue even on failure
  }, [outfitId, items, occasionContext])

  /**
   * Generate flat-lay image via API
   * Uses global queue for concurrency management
   */
  const generateFlatLay = useCallback(() => {
    // Skip if already attempted, generating, queued, or has image
    if (hasAttemptedRef.current || isGenerating || isQueued || flatLayImageBase64) {
      return
    }

    // Check cache again in case it was populated while not observing
    const cached = getCachedImage(outfitId)
    if (cached) {
      setFlatLayImageBase64(cached)
      setIsFromCache(true)
      hasAttemptedRef.current = true
      return
    }

    // Check concurrent generation limit
    if (currentGenerations >= MAX_CONCURRENT_GENERATIONS) {
      // Add to queue
      const queuedRequest: QueuedRequest = {
        id: outfitId,
        execute: performGeneration,
      }
      generationQueue.push(queuedRequest)
      setIsQueued(true)
      setQueuePosition(generationQueue.length)
      return
    }

    // Slot available, generate immediately
    performGeneration()
  }, [outfitId, isGenerating, isQueued, flatLayImageBase64, performGeneration])

  return {
    isGenerating,
    isQueued,
    queuePosition,
    flatLayImageBase64,
    error,
    generateFlatLay,
    isFromCache,
  }
}

/**
 * Hook for using Intersection Observer to trigger lazy generation
 */
export function useIntersectionObserver(
  callback: () => void,
  options?: IntersectionObserverInit
): React.RefCallback<HTMLElement> {
  const observerRef = useRef<IntersectionObserver | null>(null)
  const hasTriggeredRef = useRef(false)

  const setRef = useCallback(
    (element: HTMLElement | null) => {
      // Disconnect previous observer
      if (observerRef.current) {
        observerRef.current.disconnect()
        observerRef.current = null
      }

      // Skip if already triggered or no element
      if (hasTriggeredRef.current || !element) {
        return
      }

      observerRef.current = new IntersectionObserver(
        (entries) => {
          const [entry] = entries
          if (entry?.isIntersecting && !hasTriggeredRef.current) {
            hasTriggeredRef.current = true
            callback()
            // Disconnect after triggering
            observerRef.current?.disconnect()
          }
        },
        {
          threshold: 0.1, // Trigger when 10% visible
          ...options,
        }
      )

      observerRef.current.observe(element)
    },
    [callback, options]
  )

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      observerRef.current?.disconnect()
    }
  }, [])

  return setRef
}

